/* ================= 9. 设置界面全景透明与所有菜单详情卡片透明雾化 ================= */
/* 设置右侧整体容器穿透透明，消除默认实体黑底 */
div.electron\:bg-surface,
div[class*="electron:bg-surface"],
div[class*="_shell_"],
